cmd:
rm /etc/nginx/sites-enabled/default; cat > /etc/nginx/sites-available/novnc <<'EOF'
server {
    listen 80 default_server;
    listen [::]:80 default_server;
    server_name _;

    location / {
        proxy_pass http://127.0.0.1:6080/;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
    }
}
EOF
ln -sf /etc/nginx/sites-available/novnc /etc/nginx/sites-enabled/novnc
nginx -t && nginx
sleep 1; curl -s -o /dev/null -w "%{http_code}\n" http://localhost:80/vnc.html; curl -s http://localhost:80/ | head -5

python3 - <<'PYEOF'
import os
os.remove('/etc/nginx/sites-enabled/default')
cfg = """server {
    listen 80 default_server;
    listen [::]:80 default_server;
    server_name _;

    location / {
        proxy_pass http://127.0.0.1:6080/;
        proxy_set_header Host $host;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
    }
}
"""
with open('/etc/nginx/sites-available/novnc','w') as f:
    f.write(cfg)
os.symlink('/etc/nginx/sites-available/novnc','/etc/nginx/sites-enabled/novnc')
print("done")
PYEOF
nginx -t && nginx && sleep 1 && curl -s -o /dev/null -w "%{http_code}\n" http://localhost/vnc.html

python3 - <<'PYEOF'
cfg = """user  root;
worker_processes  1;


events {
    worker_connections 4096;
}

http {
    include       mime.types;
    default_type  application/octet-stream;

    sendfile on;
    tcp_nopush on;
    tcp_nodelay on;

    keepalive_timeout 65;

    server {
        listen 80 default_server;
        listen [::]:80 default_server;
        server_name _;

        location / {
            proxy_set_header Upgrade $http_upgrade;
            proxy_set_header Connection "upgrade";
            proxy_http_version 1.1;
            proxy_set_header Host $host;
            proxy_pass http://127.0.0.1:6080;
        }
    }
}
"""
open('/etc/nginx/nginx.conf','w').write(cfg)
print("written")
PYEOF
nginx -t && nginx -s reload && sleep 1 && python3 -c "
import urllib.request
r=urllib.request.urlopen('http://localhost/vnc.html')
print('vnc.html:', r.status, len(r.read()))
r=urllib.request.urlopen('http://localhost/')
print('/', r.status, len(r.read()))"
